    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("applyTwice add 3", 16, Applier.applyTwice(n -> n + 3, 10));
        check("applyTwice square", 81, Applier.applyTwice(n -> n * n, 3));
        check("applyTwice decrement from zero", -2, Applier.applyTwice(n -> n - 1, 0));
        check("countMatching evens", 3, Applier.countMatching(new int[] {1, 2, 3, 4, 5, 6}, n -> n % 2 == 0));
        check("countMatching negatives", 2, Applier.countMatching(new int[] {-5, 3, -1}, n -> n < 0));
        check("countMatching none", 0, Applier.countMatching(new int[] {1, 3}, n -> n > 10));
        check("countMatching empty array", 0, Applier.countMatching(new int[] {}, n -> true));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
