public class Applier {

    public static int applyTwice(java.util.function.UnaryOperator<Integer> op, int start) {
        int once = op.apply(start);
        return op.apply(once);
    }

    public static int countMatching(int[] values, java.util.function.IntPredicate p) {
        int count = 0;
        for (int value : values) {
            if (p.test(value)) {
                count++;
            }
        }
        return count;
    }
}
